#include <stdio.h>

void show(int n, char *argv[]) {
    printf("一共收到 %d 条投喂\n", n);
    for (int i = 1; i < n; i++) {
        printf("第 %d 条：%s\n", i, argv[i]);
    }
}

int main(int argc, char *argv[]) {
    show(argc, argv);
    if (argc == 1) {
        printf("这次一条都没多给喵\n");
    }
    printf("--- 下面这趟是本喵自己捏的一串投喂 ---\n");

    char *demo[3] = {"benmiao", "{a}", "{b}"};
    show(3, demo);
    return 0;
}
